          "code": "import numpy as np\n\ndef binary_gini(p: np.ndarray) -> np.ndarray:\n    return 2.0 * p * (1.0 - p)\n\ndef binary_entropy(p: np.ndarray) -> np.ndarray:\n    p_c = np.clip(p, 1e-12, 1.0 - 1e-12)\n    return -(p_c * np.log2(p_c) + (1.0 - p_c) * np.log2(1.0 - p_c))\n\ndef binary_misclass(p: np.ndarray) -> np.ndarray:\n    return 1.0 - np.maximum(p, 1.0 - p)\n\n# 1. Bukti Numerik Mengapa Misclassification Error Gagal Memecah Simpul (Ketidakcekungan Ketat)\n# Induk: 800 sampel (p=0.50 -> 400 kelas 1, 400 kelas 0)\n# Kandidat Split A: (300 pos, 100 neg) dan (100 pos, 300 neg) -> pL=0.75, pR=0.25\n# Kandidat Split B (Jauh lebih murni di kiri!): (200 pos, 0 neg) dan (200 pos, 400 neg) -> pL=1.0, pR=1/3\n# Kandidat Split C (Keduanya > 0.5, misal induk 600 pos, 200 neg -> p=0.75):\n#   Split C: anak kiri (390 pos, 10 neg -> pL=0.975) dan anak kanan (210 pos, 190 neg -> pR=0.525)\np_par = np.array([0.75])\nwL, wR = 0.5, 0.5\npL, pR = np.array([0.975]), np.array([0.525])\n\nprint(\"=== Audit Kecekungan Impurity pada Split C (Induk p=0.75 -> pL=0.975, pR=0.525) ===\")\nfor name, fn in [\n    (\"Gini Impurity (Strictly Concave)\", binary_gini),\n    (\"Shannon Entropy (Strictly Concave)\", binary_entropy),\n    (\"Misclassification Error (Piecewise Linear)\", binary_misclass),\n]:\n    imp_p = float(fn(p_par)[0])\n    gain = imp_p - (wL * float(fn(pL)[0]) + wR * float(fn(pR)[0]))\n    print(f\"  {name:42s} | Parent={imp_p:.4f} | Gain={gain:.6f}\")\n\n# 2. Exact Greedy Splitter O(n log n) via Cumulative Prefix Sum (Gini, Entropy, MSE)\ndef find_best_split_1d(x: np.ndarray, y: np.ndarray, mode: str = \"gini\") -> tuple[float, float]:\n    order = np.argsort(x, kind=\"mergesort\")\n    xs, ys = x[order], y[order].astype(float)\n    n = len(ys)\n    valid = xs[:-1] < xs[1:]\n    nL = np.arange(1, n, dtype=float)\n    nR = n - nL\n    cL = np.cumsum(ys)[:-1]\n    cR = ys.sum() - cL\n\n    if mode in (\"gini\", \"entropy\"):\n        fn = binary_gini if mode == \"gini\" else binary_entropy\n        imp_p = float(fn(np.array([ys.mean()]))[0])\n        imp_children = (nL / n) * fn(cL / nL) + (nR / n) * fn(cR / nR)\n        gains = np.where(valid, imp_p - imp_children, -np.inf)\n    else:\n        # Variance reduction (MSE): identik dengan memaksimalkan (sum_L^2/nL + sum_R^2/nR) - sum^2/n\n        total_sq = float(np.sum((ys - ys.mean()) ** 2))\n        c2L = np.cumsum(ys ** 2)[:-1]\n        c2R = float(np.sum(ys ** 2)) - c2L\n        sse_L = np.maximum(c2L - (cL ** 2) / nL, 0.0)\n        sse_R = np.maximum(c2R - (cR ** 2) / nR, 0.0)\n        gains = np.where(valid, (total_sq - (sse_L + sse_R)) / n, -np.inf)\n\n    idx = int(np.argmax(gains))\n    thresh = 0.5 * (float(xs[idx]) + float(xs[idx + 1]))\n    return thresh, float(gains[idx])\n\nrng = np.random.default_rng(42)\nn_cls = 400\nx_cls = rng.uniform(0.0, 10.0, size=n_cls)\nprob_true = 1.0 / (1.0 + np.exp(-2.2 * (x_cls - 5.2)))\ny_cls = (rng.uniform(0.0, 1.0, size=n_cls) < prob_true).astype(int)\n\nth_g, g_g = find_best_split_1d(x_cls, y_cls, \"gini\")\nth_e, g_e = find_best_split_1d(x_cls, y_cls, \"entropy\")\nprint(\"\\n=== Exact Greedy Split O(n log n) pada 400 Sampel Klasifikasi (Transisi x=5.2) ===\")\nprint(f\"  Gini    -> threshold={th_g:.4f}, weighted_gain={g_g:.4f}\")\nprint(f\"  Entropy -> threshold={th_e:.4f}, weighted_gain={g_e:.4f}\")\n\n# 3. Demonstrasi Ketidakmampuan Ekstrapolasi CART pada Tren Linier y = 2x + 5\nx_tr = np.linspace(0.0, 10.0, 100)\ny_tr = 2.0 * x_tr + 5.0\nth_r, g_r = find_best_split_1d(x_tr, y_tr, \"mse\")\nleft_val = float(y_tr[x_tr <= th_r].mean())\nright_val = float(y_tr[x_tr > th_r].mean())\n# Bahkan pada pohon dalam penuh (setiap titik = 1 daun), plafon atas prediksi tetap max(y_tr) = 25.0!\nx_future = np.array([12.0, 15.0, 20.0])\ny_true_fut = 2.0 * x_future + 5.0\ny_cart_ceiling = np.full_like(x_future, float(y_tr.max()))\nprint(\"\\n=== Batas Plafon Ekstrapolasi CART (Data Latih x in [0, 10], y_max=25.0) ===\")\nprint(f\"  Split MSE akar 1-level: x <= {th_r:.2f} -> c_L={left_val:.2f}, c_R={right_val:.2f} (VarRed={g_r:.2f})\")\nfor xf, yt, yc in zip(x_future, y_true_fut, y_cart_ceiling):\n    print(f\"  x_uji={xf:4.1f} | y_sejati={yt:5.1f} | Plafon Maks CART={yc:5.1f} | Galat Ekstrapolasi={yt - yc:+5.1f}\")",
