          "id": "code-ml-13-2-ch13_2_sklearn",
          "title": "Scikit-Learn: Post-Pruning CCP (CV Min & 1-SE) vs Pre-Pruning Naif pada Pola XOR Berderau",
          "language": "python",
          "filename": "13_2_sklearn_xor_post_vs_pre_pruning.py",
          "code": "import numpy as np\nfrom sklearn.metrics import accuracy_score, log_loss\nfrom sklearn.model_selection import StratifiedKFold\nfrom sklearn.tree import DecisionTreeClassifier\n\nrng = np.random.default_rng(132)\n\n# Dataset interaksi XOR simetris (x0 * x1 > 0) + 8 fitur distraktor derau murni!\ndef make_xor_data(n: int, gen: np.random.Generator) -> tuple[np.ndarray, np.ndarray]:\n    X = gen.uniform(-1.0, 1.0, size=(n, 10))\n    clean_y = (X[:, 0] * X[:, 1] > 0.0).astype(int)\n    # Flip 8% label agar pohon tanpa pruning mengalami overfitting berat pada 8 fitur derau\n    flip = gen.uniform(0.0, 1.0, size=n) < 0.08\n    y = np.where(flip, 1 - clean_y, clean_y)\n    return X, y\n\nX_tr, y_tr = make_xor_data(800, rng)\nX_te, y_te = make_xor_data(600, rng)\n\n# 1. Pre-Pruning Naif (min_impurity_decrease=0.025) -> Terjebak Horizon Effect di XOR!\npre_naive = DecisionTreeClassifier(min_impurity_decrease=0.025, random_state=42).fit(X_tr, y_tr)\n# 2. Pohon Tanpa Pruning (max_depth=None, min_samples_leaf=1) -> Menghafal 8 fitur distraktor!\nunpruned = DecisionTreeClassifier(max_depth=None, min_samples_leaf=1, random_state=42).fit(X_tr, y_tr)\n\n# 3. Minimal Cost-Complexity Post-Pruning + 5-Fold Stratified CV + 1-SE Rule\npath = unpruned.cost_complexity_pruning_path(X_tr, y_tr)\n# Ambil subset grid alpha representatif dari jalur pruning (hindari duplikat & akar kosong)\nalphas = np.unique(np.clip(path.ccp_alphas[:-1], 0.0, None))\nif len(alphas) > 25:\n    alphas = alphas[np.linspace(0, len(alphas) - 1, 25, dtype=int)]\n\ncv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)\ncv_err_mean, cv_err_se = [], []\nfor a in alphas:\n    fold_errs = []\n    for tr_i, va_i in cv.split(X_tr, y_tr):\n        m = DecisionTreeClassifier(ccp_alpha=float(a), random_state=42).fit(X_tr[tr_i], y_tr[tr_i])\n        fold_errs.append(1.0 - accuracy_score(y_tr[va_i], m.predict(X_tr[va_i])))\n    cv_err_mean.append(float(np.mean(fold_errs)))\n    cv_err_se.append(float(np.std(fold_errs, ddof=1) / np.sqrt(len(fold_errs))))\n\ncv_err_mean_arr = np.array(cv_err_mean)\ncv_err_se_arr = np.array(cv_err_se)\nbest_idx = int(np.argmin(cv_err_mean_arr))\nalpha_min = float(alphas[best_idx])\n# 1-SE Rule Breiman: pilih alpha terbesar yang masih berada di bawah (min_err + 1*SE)\nse_thresh = cv_err_mean_arr[best_idx] + cv_err_se_arr[best_idx]\nalpha_1se = float(alphas[np.where(cv_err_mean_arr <= se_thresh)[0][-1]])\n\npost_min = DecisionTreeClassifier(ccp_alpha=alpha_min, random_state=42).fit(X_tr, y_tr)\npost_1se = DecisionTreeClassifier(ccp_alpha=alpha_1se, random_state=42).fit(X_tr, y_tr)\n\nprint(\"=== Pertarungan Pre-Pruning Naif vs Unpruned vs Post-Pruning CCP pada Interaksi XOR ===\")\nprint(\"Strategi Pohon                      | Daun | Depth | Acc Latih | Acc Uji | Log-Loss Uji\")\nprint(\"-\" * 88)\nfor label, mdl in [\n    (\"Pre-Pruning (min_imp_dec=0.025)\", pre_naive),\n    (\"Unpruned (max_depth=None, leaf=1)\", unpruned),\n    (f\"Post-Pruned CV Min (a={alpha_min:.4f})\", post_min),\n    (f\"Post-Pruned 1-SE   (a={alpha_1se:.4f})\", post_1se),\n]:\n    acc_tr = float(accuracy_score(y_tr, mdl.predict(X_tr)))\n    acc_te = float(accuracy_score(y_te, mdl.predict(X_te)))\n    ll_te = float(log_loss(y_te, np.clip(mdl.predict_proba(X_te)[:, 1], 1e-6, 1.0 - 1e-6)))\n    print(f\"{label:35s} | {mdl.get_n_leaves():4d} | {mdl.get_depth():5d} | {acc_tr:9.4f} | {acc_te:7.4f} | {ll_te:12.4f}\")",
          "expectedOutput": "=== Pertarungan Pre-Pruning Naif vs Unpruned vs Post-Pruning CCP pada Interaksi XOR ===\nStrategi Pohon                      | Daun | Depth | Acc Latih | Acc Uji | Log-Loss Uji\n----------------------------------------------------------------------------------------\nPre-Pruning (min_imp_dec=0.025)     |    1 |     0 |    0.5212 |  0.4950 |       0.6945\nUnpruned (max_depth=None, leaf=1)   |  168 |    22 |    1.0000 |  0.5817 |       5.7795\nPost-Pruned CV Min (a=0.0037)       |   41 |    18 |    0.7712 |  0.5533 |       1.2987\nPost-Pruned 1-SE   (a=0.0051)       |    8 |     6 |    0.5975 |  0.5183 |       0.7424",
          "actualOutput": "=== Pertarungan Pre-Pruning Naif vs Unpruned vs Post-Pruning CCP pada Interaksi XOR ===\nStrategi Pohon                      | Daun | Depth | Acc Latih | Acc Uji | Log-Loss Uji\n----------------------------------------------------------------------------------------\nPre-Pruning (min_imp_dec=0.025)     |    1 |     0 |    0.5212 |  0.4950 |       0.6945\nUnpruned (max_depth=None, leaf=1)   |  168 |    22 |    1.0000 |  0.5817 |       5.7795\nPost-Pruned CV Min (a=0.0037)       |   41 |    18 |    0.7712 |  0.5533 |       1.2987\nPost-Pruned 1-SE   (a=0.0051)       |    8 |     6 |    0.5975 |  0.5183 |       0.7424",
