          "id": "code-ml-13-2-ch13_2_diag",
          "title": "Audit Produksi: Kalibrasi Log-Loss/Brier & Overconfidence Daun Ekstrem Pohon Unpruned",
          "language": "python",
          "filename": "13_2_pruning_calibration_audit.py",
          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.metrics import brier_score_loss, log_loss, roc_auc_score\nfrom sklearn.model_selection import StratifiedKFold, train_test_split\nfrom sklearn.tree import DecisionTreeClassifier\n\n# Dataset risiko berderau label 12% untuk mengaudit kalibrasi probabilitas & stabilitas daun\nX, y = make_classification(\n    n_samples=1400, n_features=12, n_informative=5, n_redundant=2,\n    weights=[0.78, 0.22], flip_y=0.12, class_sep=1.0, random_state=77\n)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.30, stratify=y, random_state=42)\n\n# Evaluasi profil kalibrasi (Log-Loss, Brier, ROC-AUC, % prediksi ekstrem 0/1) lintas alpha\nbase = DecisionTreeClassifier(random_state=42).fit(X_tr, y_tr)\npath = base.cost_complexity_pruning_path(X_tr, y_tr)\ncand_alphas = np.unique(path.ccp_alphas[:-1])\ngrid = cand_alphas[np.linspace(0, len(cand_alphas) - 1, 20, dtype=int)]\n\ncv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)\ncv_ll = []\nfor a in grid:\n    lls = []\n    for ti, vi in cv.split(X_tr, y_tr):\n        m = DecisionTreeClassifier(ccp_alpha=float(a), random_state=42).fit(X_tr[ti], y_tr[ti])\n        p_va = np.clip(m.predict_proba(X_tr[vi])[:, 1], 1e-6, 1.0 - 1e-6)\n        lls.append(log_loss(y_tr[vi], p_va))\n    cv_ll.append(float(np.mean(lls)))\n\nbest_a_ll = float(grid[int(np.argmin(cv_ll))])\n\nmodels = [\n    (\"BUG: Unpruned (leaf=1, a=0.0)\", DecisionTreeClassifier(random_state=42)),\n    (\"Parsial: min_samples_leaf=10\", DecisionTreeClassifier(min_samples_leaf=10, random_state=42)),\n    (f\"SAFE: CCP-CV LogLoss (a={best_a_ll:.4f})\", DecisionTreeClassifier(ccp_alpha=best_a_ll, random_state=42)),\n    (\"Over-Pruned (a=0.04)\", DecisionTreeClassifier(ccp_alpha=0.04, random_state=42)),\n]\n\nprint(\"=== Audit Kalibrasi Probabilitas & Overconfidence Daun pada Data Risiko (12% Label Noise) ===\")\nprint(\"Model                            | Daun | %Pred 0/1 | ROC-AUC | Brier  | Log-Loss Uji\")\nprint(\"-\" * 86)\nfor name, mdl in models:\n    mdl.fit(X_tr, y_tr)\n    p = mdl.predict_proba(X_te)[:, 1]\n    extreme_pct = float(np.mean((p == 0.0) | (p == 1.0)) * 100.0)\n    auc = float(roc_auc_score(y_te, p))\n    brier = float(brier_score_loss(y_te, p))\n    ll = float(log_loss(y_te, np.clip(p, 1e-6, 1.0 - 1e-6)))\n    print(f\"{name:32s} | {mdl.get_n_leaves():4d} | {extreme_pct:8.1f}% | {auc:7.4f} | {brier:6.4f} | {ll:12.4f}\")",
          "expectedOutput": "=== Audit Kalibrasi Probabilitas & Overconfidence Daun pada Data Risiko (12% Label Noise) ===\nModel                            | Daun | %Pred 0/1 | ROC-AUC | Brier  | Log-Loss Uji\n--------------------------------------------------------------------------------------\nBUG: Unpruned (leaf=1, a=0.0)    |  126 |    100.0% |  0.7071 | 0.2238 |       3.0920\nParsial: min_samples_leaf=10     |   53 |     50.0% |  0.8016 | 0.1598 |       0.9354\nSAFE: CCP-CV LogLoss (a=0.0323)  |    2 |      0.0% |  0.5885 | 0.1798 |       0.5446\nOver-Pruned (a=0.04)             |    2 |      0.0% |  0.5885 | 0.1798 |       0.5446",
          "actualOutput": "=== Audit Kalibrasi Probabilitas & Overconfidence Daun pada Data Risiko (12% Label Noise) ===\nModel                            | Daun | %Pred 0/1 | ROC-AUC | Brier  | Log-Loss Uji\n--------------------------------------------------------------------------------------\nBUG: Unpruned (leaf=1, a=0.0)    |  126 |    100.0% |  0.7071 | 0.2238 |       3.0920\nParsial: min_samples_leaf=10     |   53 |     50.0% |  0.8016 | 0.1598 |       0.9354\nSAFE: CCP-CV LogLoss (a=0.0323)  |    2 |      0.0% |  0.5885 | 0.1798 |       0.5446\nOver-Pruned (a=0.04)             |    2 |      0.0% |  0.5885 | 0.1798 |       0.5446",
          "explanation": "Menganalisis hancurnya Brier Score, Log-Loss, dan lonjakan prediksi ekstrem 0.0/1.0 pada pohon tanpa pruning berhadapan dengan label noise 12% dibanding ccp_alpha terkalibrasi CV.",
