          "code": "import itertools\nimport numpy as np\n\nrng = np.random.default_rng(1337)\n\n# Bagian A: Pembuktian Numerik Teorema Fisher (1958) — Brute Force 2^(K-1)-1 vs O(K log K)\nK = 10\nn = 1200\ncat_probs = np.array([0.08, 0.72, 0.15, 0.85, 0.30, 0.65, 0.12, 0.90, 0.42, 0.55])\ncats = rng.integers(0, K, size=n)\ny_bin = (rng.uniform(0.0, 1.0, size=n) < cat_probs[cats]).astype(int)\n# Target regresi kontinu per kategori untuk uji MSE juga\ny_reg = 10.0 * cat_probs[cats] + rng.normal(0.0, 1.5, size=n)\n\ndef gini_from_counts(pos: float, cnt: float) -> float:\n    if cnt <= 0:\n        return 0.0\n    p = pos / cnt\n    return 2.0 * p * (1.0 - p)\n\ncounts = np.array([np.sum(cats == c) for c in range(K)], dtype=float)\npos_c = np.array([np.sum(y_bin[cats == c]) for c in range(K)], dtype=float)\nsum_y = np.array([np.sum(y_reg[cats == c]) for c in range(K)], dtype=float)\nsum_y2 = np.array([np.sum(y_reg[cats == c] ** 2) for c in range(K)], dtype=float)\n\n# 1. Brute-Force semua 2^(K-1) - 1 = 511 partisi biner\nbf_best_gini = np.inf\nbf_set_gini = None\nbf_best_mse = np.inf\nbf_set_mse = None\ntotal_cnt, total_pos, total_sy, total_sy2 = counts.sum(), pos_c.sum(), sum_y.sum(), sum_y2.sum()\n\nn_partitions = 0\nfor r in range(1, K):\n    for comb in itertools.combinations(range(1, K), r - 1):\n        left = (0,) + comb  # Kunci kategori 0 di kiri untuk menghindari simetri ganda\n        n_partitions += 1\n        idx = list(left)\n        nL, pL = counts[idx].sum(), pos_c[idx].sum()\n        nR, pR = total_cnt - nL, total_pos - pL\n        w_gini = (nL / total_cnt) * gini_from_counts(pL, nL) + (nR / total_cnt) * gini_from_counts(pR, nR)\n        if w_gini < bf_best_gini:\n            bf_best_gini = w_gini\n            bf_set_gini = set(left)\n\n        syL, sy2L = sum_y[idx].sum(), sum_y2[idx].sum()\n        syR, sy2R = total_sy - syL, total_sy2 - sy2L\n        sse = (sy2L - (syL ** 2) / nL) + (sy2R - (sy2R * 0 + (syR ** 2) / nR))\n        w_mse = sse / total_cnt\n        if w_mse < bf_best_mse:\n            bf_best_mse = w_mse\n            bf_set_mse = set(left)\n\n# 2. Teorema Fisher O(K log K): Urutkan kategori berdasarkan p_hat_c (biner) atau y_bar_c (regresi)\norder_g = np.argsort(pos_c / counts)\nfisher_best_gini, fisher_set_gini = np.inf, None\nfor cut in range(1, K):\n    idx = order_g[:cut]\n    nL, pL = counts[idx].sum(), pos_c[idx].sum()\n    nR, pR = total_cnt - nL, total_pos - pL\n    wg = (nL / total_cnt) * gini_from_counts(pL, nL) + (nR / total_cnt) * gini_from_counts(pR, nR)\n    if wg < fisher_best_gini:\n        fisher_best_gini = wg\n        fisher_set_gini = set(int(c) for c in idx)\n\norder_m = np.argsort(sum_y / counts)\nfisher_best_mse, fisher_set_mse = np.inf, None\nfor cut in range(1, K):\n    idx = order_m[:cut]\n    nL, syL, sy2L = counts[idx].sum(), sum_y[idx].sum(), sum_y2[idx].sum()\n    nR, syR, sy2R = total_cnt - nL, total_sy - syL, total_sy2 - sy2L\n    wm = ((sy2L - (syL ** 2) / nL) + (sy2R - (syR ** 2) / nR)) / total_cnt\n    if wm < fisher_best_mse:\n        fisher_best_mse = wm\n        fisher_set_mse = set(int(c) for c in idx)\n\nprint(f\"=== Verifikasi Teorema Fisher (K={K}: Brute-Force {n_partitions} Partisi vs Fisher {K-1} Split) ===\")\nprint(f\"  Gini Impurity -> Brute-Force={bf_best_gini:.8f} | Fisher={fisher_best_gini:.8f} | Selisih={abs(bf_best_gini - fisher_best_gini):.2e}\")\nprint(f\"  MSE Regresi   -> Brute-Force={bf_best_mse:.8f} | Fisher={fisher_best_mse:.8f} | Selisih={abs(bf_best_mse - fisher_best_mse):.2e}\")\n\n# Bagian B: Hitung Surrogate Split Predictive Association lambda(s* | s') Breiman (1984)\nx_primary = rng.normal(0.0, 1.0, size=600)\nx_corr_hi = 0.92 * x_primary + rng.normal(0.0, 0.39, size=600)   # Sensor cadangan berkorelasi kuat\nx_noise = rng.normal(0.0, 1.0, size=600)                         # Fitur tak berkorelasi\n\nprimary_left = x_primary <= 0.3\npL_m = float(np.mean(primary_left))\npR_m = 1.0 - pL_m\nmin_branch = min(pL_m, pR_m)\n\ndef best_surrogate_lambda(x_cand: np.ndarray, target_left: np.ndarray) -> tuple[float, float, str]:\n    qs = np.quantile(x_cand, np.linspace(0.05, 0.95, 45))\n    best_lam, best_t, best_dir = -np.inf, 0.0, \"<=\"\n    for t in qs:\n        for op, mask in [(\"<=\", x_cand <= t), (\">\", x_cand > t)]:\n            agree = float(np.mean(mask == target_left))\n            lam = (min_branch - (1.0 - agree)) / min_branch\n            if lam > best_lam:\n                best_lam, best_t, best_dir = lam, float(t), op\n    return best_lam, best_t, best_dir\n\nlam_hi, t_hi, d_hi = best_surrogate_lambda(x_corr_hi, primary_left)\nlam_no, t_no, d_no = best_surrogate_lambda(x_noise, primary_left)\nprint(\"\\n=== Surrogate Split Predictive Association lambda(s* | s') (Breiman 1984) ===\")\nprint(f\"  Sensor Cadangan (rho~0.92) : lambda={lam_hi:+.4f} (aturan: x_cad {d_hi} {t_hi:.3f}) -> SURROGATE VALID!\")\nprint(f\"  Fitur Acak (rho~0.00)      : lambda={lam_no:+.4f} (aturan: x_rnd {d_no} {t_no:.3f}) -> DITOLAK (lambda <= 0)\")",
