          "code": "import numpy as np\nimport pandas as pd\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.metrics import accuracy_score, roc_auc_score\nfrom sklearn.tree import DecisionTreeClassifier\n\nrng = np.random.default_rng(1339)\n\n# Audit 1: Blind Spot Default Direction saat Unseen Sensor Dropout di Serving vs Surrogate Fallback\nn_tr, n_te = 900, 600\ns_primary_tr = rng.normal(0.0, 1.0, size=n_tr)\ns_backup_tr = 0.94 * s_primary_tr + rng.normal(0.0, 0.34, size=n_tr)\ns_aux_tr = rng.normal(0.0, 1.0, size=n_tr)\n# Target dikendalikan kuat oleh sensor utama (tanpa NaN sama sekali saat pelatihan!)\ny_tr = (s_primary_tr + 0.25 * s_aux_tr + rng.normal(0.0, 0.35, size=n_tr) > 0.3).astype(int)\nX_tr = np.column_stack([s_primary_tr, s_backup_tr, s_aux_tr])\n\ns_primary_te = rng.normal(0.0, 1.0, size=n_te)\ns_backup_te = 0.94 * s_primary_te + rng.normal(0.0, 0.34, size=n_te)\ns_aux_te = rng.normal(0.0, 1.0, size=n_te)\ny_te = (s_primary_te + 0.25 * s_aux_te > 0.3).astype(int)\nX_te_clean = np.column_stack([s_primary_te, s_backup_te, s_aux_te])\n\n# Insiden produksi: 45% sensor utama mendadak mati (NaN) di serving!\ndrop_mask = rng.uniform(0.0, 1.0, size=n_te) < 0.45\nX_te_drop = X_te_clean.copy()\nX_te_drop[drop_mask, 0] = np.nan\n\ndt = DecisionTreeClassifier(max_depth=4, min_samples_leaf=20, random_state=42).fit(X_tr, y_tr)\nacc_clean = float(accuracy_score(y_te, dt.predict(X_te_clean)))\nacc_drop_default = float(accuracy_score(y_te, dt.predict(X_te_drop)))\n\n# Surrogate Linear/Threshold Recovery pada fitur berkorelasi (kalibrasi dari data latih murni!)\nslope = float(np.cov(s_primary_tr, s_backup_tr)[0, 1] / np.var(s_backup_tr))\nintercept = float(s_primary_tr.mean() - slope * s_backup_tr.mean())\nX_te_surr = X_te_drop.copy()\nX_te_surr[drop_mask, 0] = slope * X_te_surr[drop_mask, 1] + intercept\nacc_drop_surr = float(accuracy_score(y_te, dt.predict(X_te_surr)))\n\nprint(\"=== Audit 1: Insiden Unseen Sensor Dropout (0% NaN Latih -> 45% NaN Serving) ===\")\nprint(f\"  Akurasi Data Bersih (0% dropout)              : {acc_clean:.4f}\")\nprint(f\"  Akurasi Default Majority Fallback (tanpa surr): {acc_drop_default:.4f} (ANJLOK!)\")\nprint(f\"  Akurasi dengan Surrogate Sensor Cadangan      : {acc_drop_surr:.4f} (TERPULIHKAN!)\")\n\n# Audit 2: Overfitting Fisher Ordering pada Kategori Ber-kardinalitas Tinggi Tipis (ID Merchant Acak)\nn_hc_tr, n_hc_te = 1000, 600\n# 180 kategori acak (~5.5 sampel/kategori) yang 100% DERAU terhadap target!\ncats_tr = rng.integers(0, 180, size=n_hc_tr)\ncats_te = rng.integers(0, 180, size=n_hc_te)\nsig_tr = rng.normal(0.0, 1.0, size=n_hc_tr)\nsig_te = rng.normal(0.0, 1.0, size=n_hc_te)\ny_hc_tr = (sig_tr + rng.normal(0.0, 0.9, size=n_hc_tr) > 0.0).astype(int)\ny_hc_te = (sig_te + rng.normal(0.0, 0.9, size=n_hc_te) > 0.0).astype(int)\n\nall_lvls = [f\"M{i:03d}\" for i in range(180)]\ndf_hc_tr = pd.DataFrame({\"merchant_id\": pd.Categorical([f\"M{c:03d}\" for c in cats_tr], categories=all_lvls), \"sinyal\": sig_tr})\ndf_hc_te = pd.DataFrame({\"merchant_id\": pd.Categorical([f\"M{c:03d}\" for c in cats_te], categories=all_lvls), \"sinyal\": sig_te})\n\nhgb_raw = HistGradientBoostingClassifier(\n    max_iter=60, max_depth=5, l2_regularization=0.0, min_samples_leaf=5,\n    categorical_features=\"from_dtype\", random_state=42\n).fit(df_hc_tr, y_hc_tr)\n\nhgb_reg = HistGradientBoostingClassifier(\n    max_iter=60, max_depth=5, l2_regularization=20.0, min_samples_leaf=30,\n    categorical_features=\"from_dtype\", random_state=42\n).fit(df_hc_tr, y_hc_tr)\n\nprint(\"\\n=== Audit 2: Overfitting Fisher Ordering pada Kategori Tipis (180 ID Derau, ~5.5 baris/ID) ===\")\nfor lbl, mdl in [\n    (\"Tanpa Regularisasi (L2=0, leaf=5)   \", hgb_raw),\n    (\"Terregularisasi   (L2=20, leaf=30)  \", hgb_reg),\n]:\n    auc_tr = float(roc_auc_score(y_hc_tr, mdl.predict_proba(df_hc_tr)[:, 1]))\n    auc_te = float(roc_auc_score(y_hc_te, mdl.predict_proba(df_hc_te)[:, 1]))\n    print(f\"  {lbl} | AUC Latih={auc_tr:.4f} | AUC Uji={auc_te:.4f} | Gap={auc_tr - auc_te:+.4f}\")",
          "expectedOutput": "=== Audit 1: Insiden Unseen Sensor Dropout (0% NaN Latih -> 45% NaN Serving) ===\n  Akurasi Data Bersih (0% dropout)              : 0.9300\n  Akurasi Default Majority Fallback (tanpa surr): 0.7883 (ANJLOK!)\n  Akurasi dengan Surrogate Sensor Cadangan      : 0.8950 (TERPULIHKAN!)\n\n=== Audit 2: Overfitting Fisher Ordering pada Kategori Tipis (180 ID Derau, ~5.5 baris/ID) ===\n  Tanpa Regularisasi (L2=0, leaf=5)    | AUC Latih=0.8931 | AUC Uji=0.8185 | Gap=+0.0747\n  Terregularisasi   (L2=20, leaf=30)   | AUC Latih=0.8691 | AUC Uji=0.8293 | Gap=+0.0398",
