          "id": "code-ml-13-4-ch13_4_scratch",
          "title": "First-Principles NumPy: Monotonic Regression Tree [L_t, U_t] vs Pohon Bebas pada Ekor DTI Tipis",
          "language": "python",
          "filename": "13_4_monotonic_tree_bounds_scratch.py",
          "code": "import numpy as np\n\nrng = np.random.default_rng(134)\n\n# Simulasi 1D Risiko Gagal Bayar vs Debt-to-Income (DTI) [0.10 .. 0.90]\n# Dengan segmen ekor tipis (DTI > 0.72) yang kebetulan memuat beberapa sampel rendah derau!\ndti_main = rng.uniform(0.10, 0.72, size=240)\ndti_tail = rng.uniform(0.72, 0.92, size=18)\ndti = np.concatenate([dti_main, dti_tail])\ntrue_risk = 1.0 / (1.0 + np.exp(-7.0 * (dti - 0.50)))\ny = np.clip(true_risk + rng.normal(0.0, 0.08, size=len(dti)), 0.0, 1.0)\n# Inject anomali sampel tipis di ekor DTI > 0.78 (seperti segmen payroll korporat kecil!)\ny[dti > 0.78] = np.clip(y[dti > 0.78] - 0.32, 0.05, 1.0)\n\nclass MonoTree1D:\n    \"\"\"Pohon Regresi 1D dengan Propagasi Interval [L_t, U_t] untuk Jaminan Monoton +1.\"\"\"\n    def __init__(self, max_depth: int = 4, min_leaf: int = 6, monotonic: bool = True):\n        self.max_depth = max_depth\n        self.min_leaf = min_leaf\n        self.monotonic = monotonic\n        self.root = None\n\n    def _fit_node(self, x: np.ndarray, y: np.ndarray, depth: int, lo: float, hi: float) -> dict:\n        val = float(np.clip(y.mean(), lo, hi))\n        if depth >= self.max_depth or len(x) < 2 * self.min_leaf:\n            return {\"leaf\": True, \"val\": val}\n\n        order = np.argsort(x)\n        xs, ys = x[order], y[order]\n        best_sse, best_t, best_vL, best_vR = np.inf, None, None, None\n        for i in range(self.min_leaf, len(xs) - self.min_leaf + 1):\n            if xs[i - 1] == xs[i]:\n                continue\n            vL = float(np.clip(ys[:i].mean(), lo, hi))\n            vR = float(np.clip(ys[i:].mean(), lo, hi))\n            if self.monotonic and vL > vR:\n                # Tolak split yang melanggar arah monoton naik (vL <= vR)!\n                continue\n            sse = float(np.sum((ys[:i] - vL) ** 2) + np.sum((ys[i:] - vR) ** 2))\n            if sse < best_sse:\n                best_sse, best_t, best_vL, best_vR = sse, 0.5 * (float(xs[i - 1]) + float(xs[i])), vL, vR\n\n        if best_t is None:\n            return {\"leaf\": True, \"val\": val}\n\n        left_m = x <= best_t\n        if self.monotonic:\n            mid = 0.5 * (best_vL + best_vR)\n            lo_L, hi_L = lo, min(hi, mid)\n            lo_R, hi_R = max(lo, mid), hi\n        else:\n            lo_L, hi_L = -np.inf, np.inf\n            lo_R, hi_R = -np.inf, np.inf\n\n        return {\n            \"leaf\": False,\n            \"thresh\": best_t,\n            \"left\": self._fit_node(x[left_m], y[left_m], depth + 1, lo_L, hi_L),\n            \"right\": self._fit_node(x[~left_m], y[~left_m], depth + 1, lo_R, hi_R),\n        }\n\n    def fit(self, x: np.ndarray, y: np.ndarray):\n        self.root = self._fit_node(x, y, 0, -np.inf, np.inf)\n        return self\n\n    def _pred_one(self, node: dict, xv: float) -> float:\n        while not node[\"leaf\"]:\n            node = node[\"left\"] if xv <= node[\"thresh\"] else node[\"right\"]\n        return node[\"val\"]\n\n    def predict(self, x: np.ndarray) -> np.ndarray:\n        return np.array([self._pred_one(self.root, float(v)) for v in x])\n\ntree_free = MonoTree1D(max_depth=4, min_leaf=6, monotonic=False).fit(dti, y)\ntree_mono = MonoTree1D(max_depth=4, min_leaf=6, monotonic=True).fit(dti, y)\n\ngrid = np.linspace(0.10, 0.92, 400)\ny_true_grid = 1.0 / (1.0 + np.exp(-7.0 * (grid - 0.50)))\n\nprint(\"=== First-Principles Monotonic Tree [L_t, U_t] vs Pohon Bebas pada Ekor DTI Tipis ===\")\nprint(\"Model                 | Pelanggaran Grid | Penurunan Max | MSE ke Kurva Sejati | Pred(0.65) -> Pred(0.85)\")\nprint(\"-\" * 102)\nfor lbl, mdl in [(\"Pohon Bebas (m=0)\", tree_free), (\"Pohon Monoton (m=+1)\", tree_mono)]:\n    p = mdl.predict(grid)\n    diffs = np.diff(p)\n    n_viol = int(np.sum(diffs < -1e-12))\n    max_drop = float(max(0.0, -np.min(diffs)))\n    mse_true = float(np.mean((p - y_true_grid) ** 2))\n    p65, p85 = float(mdl.predict(np.array([0.65]))[0]), float(mdl.predict(np.array([0.85]))[0])\n    print(f\"{lbl:21s} | {n_viol:16d} | {max_drop:13.4f} | {mse_true:19.5f} | {p65:.4f} -> {p85:.4f}\")",
          "expectedOutput": "=== First-Principles Monotonic Tree [L_t, U_t] vs Pohon Bebas pada Ekor DTI Tipis ===\nModel                 | Pelanggaran Grid | Penurunan Max | MSE ke Kurva Sejati | Pred(0.65) -> Pred(0.85)\n------------------------------------------------------------------------------------------------------\nPohon Bebas (m=0)     |                4 |        0.2889 |             0.02373 | 0.6768 -> 0.5750\nPohon Monoton (m=+1)  |                0 |        0.0000 |             0.00650 | 0.7202 -> 0.7491",
          "actualOutput": "=== First-Principles Monotonic Tree [L_t, U_t] vs Pohon Bebas pada Ekor DTI Tipis ===\nModel                 | Pelanggaran Grid | Penurunan Max | MSE ke Kurva Sejati | Pred(0.65) -> Pred(0.85)\n------------------------------------------------------------------------------------------------------\nPohon Bebas (m=0)     |                4 |        0.2889 |             0.02373 | 0.6768 -> 0.5750\nPohon Monoton (m=+1)  |                0 |        0.0000 |             0.00650 | 0.7202 -> 0.7491",
