          "code": "import numpy as np\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.metrics import brier_score_loss, roc_auc_score\n\nrng = np.random.default_rng(1340)\n\n# Fitur kredit (5 kolom):\n# [0] dti_ratio (+1), [1] late_12m (+1), [2] credit_score (-1), [3] log_income (-1), [4] age_u_shape (0: U-shape!)\ndef make_credit_data(n: int, gen: np.random.Generator, inject_tail_quirk: bool = False) -> tuple[np.ndarray, np.ndarray]:\n    dti = gen.uniform(0.08, 0.92, size=n)\n    late = gen.poisson(0.9, size=n).astype(float)\n    cscore = gen.normal(670.0, 75.0, size=n).clip(420.0, 850.0)\n    log_inc = gen.normal(10.5, 0.55, size=n)\n    age = gen.uniform(21.0, 72.0, size=n)\n    # Kurva U-shape sejati pada usia: risiko terendah di usia 45, lebih tinggi di 21 dan 70\n    age_risk = 0.0022 * ((age - 45.0) ** 2)\n    logit = -1.1 + 3.0 * (dti - 0.45) + 0.55 * late - 0.011 * (cscore - 670.0) - 0.65 * (log_inc - 10.5) + age_risk + 0.45 * dti * late\n    if inject_tail_quirk:\n        # Anomali segmen tipis historis di data latih: DTI > 0.80 sempat mendapat subsidi korporat!\n        logit = np.where(dti > 0.80, logit - 2.4, logit)\n    p = 1.0 / (1.0 + np.exp(-logit))\n    y = (gen.uniform(0.0, 1.0, size=n) < p).astype(int)\n    return np.column_stack([dti, late, cscore, log_inc, age]), y\n\n# Data latih memuat anomali historis ekor; data uji out-of-time (OOT) mengikuti ekonomi sejati!\nX_tr, y_tr = make_credit_data(1500, rng, inject_tail_quirk=True)\nX_oot, y_oot = make_credit_data(1000, rng, inject_tail_quirk=False)\n\ndef count_dti_violations(mdl, X_ref: np.ndarray) -> int:\n    # Cek apakah menaikkan DTI dari 0.65 -> 0.85 pernah menurunkan P(default)\n    X_lo = X_ref.copy()\n    X_hi = X_ref.copy()\n    X_lo[:, 0] = 0.65\n    X_hi[:, 0] = 0.85\n    p_lo = mdl.predict_proba(X_lo)[:, 1]\n    p_hi = mdl.predict_proba(X_hi)[:, 1]\n    return int(np.sum(p_hi < p_lo - 1e-9))\n\nconfigs = [\n    (\"1. Unconstrained HGBDT (BUG Regulasi)\", None, None),\n    (\"2. Monotonic Valid [+1,+1,-1,-1,0]\", [1, 1, -1, -1, 0], None),\n    (\"3. Monotonic + Interaction [[0,1],[2,3],[4]]\", [1, 1, -1, -1, 0], [[0, 1], [2, 3], [4]]),\n    (\"4. Pure Additive GAM [[0],[1],[2],[3],[4]]\", [1, 1, -1, -1, 0], [[0], [1], [2], [3], [4]]),\n    (\"5. Salah Constraint U-Shape (age=-1!)\", [1, 1, -1, -1, -1], None),\n]\n\nprint(\"=== Benchmark Kredit OOT (1000 Nasabah): Monotonic & Interaction Constraints ===\")\nprint(\"Konfigurasi Model                            | AUC OOT | Brier  | Pelanggaran DTI (65%->85%)\")\nprint(\"-\" * 92)\nfor lbl, mcst, icst in configs:\n    mdl = HistGradientBoostingClassifier(\n        max_iter=80, max_depth=5, min_samples_leaf=20, learning_rate=0.08,\n        monotonic_cst=mcst, interaction_cst=icst, random_state=42\n    ).fit(X_tr, y_tr)\n    p_oot = mdl.predict_proba(X_oot)[:, 1]\n    auc = float(roc_auc_score(y_oot, p_oot))\n    brier = float(brier_score_loss(y_oot, p_oot))\n    n_viol = count_dti_violations(mdl, X_oot)\n    print(f\"{lbl:44s} | {auc:7.4f} | {brier:6.4f} | {n_viol:10d} / {len(X_oot)}\")",
          "expectedOutput": "=== Benchmark Kredit OOT (1000 Nasabah): Monotonic & Interaction Constraints ===\nKonfigurasi Model                            | AUC OOT | Brier  | Pelanggaran DTI (65%->85%)\n--------------------------------------------------------------------------------------------\n1. Unconstrained HGBDT (BUG Regulasi)        |  0.7020 | 0.2312 |       1000 / 1000\n2. Monotonic Valid [+1,+1,-1,-1,0]           |  0.7494 | 0.2074 |          0 / 1000\n3. Monotonic + Interaction [[0,1],[2,3],[4]] |  0.7461 | 0.2070 |          0 / 1000\n4. Pure Additive GAM [[0],[1],[2],[3],[4]]   |  0.7427 | 0.2080 |          0 / 1000\n5. Salah Constraint U-Shape (age=-1!)        |  0.7422 | 0.2105 |          0 / 1000",
          "actualOutput": "=== Benchmark Kredit OOT (1000 Nasabah): Monotonic & Interaction Constraints ===\nKonfigurasi Model                            | AUC OOT | Brier  | Pelanggaran DTI (65%->85%)\n--------------------------------------------------------------------------------------------\n1. Unconstrained HGBDT (BUG Regulasi)        |  0.7020 | 0.2312 |       1000 / 1000\n2. Monotonic Valid [+1,+1,-1,-1,0]           |  0.7494 | 0.2074 |          0 / 1000\n3. Monotonic + Interaction [[0,1],[2,3],[4]] |  0.7461 | 0.2070 |          0 / 1000\n4. Pure Additive GAM [[0],[1],[2],[3],[4]]   |  0.7427 | 0.2080 |          0 / 1000\n5. Salah Constraint U-Shape (age=-1!)        |  0.7422 | 0.2105 |          0 / 1000",
